"use client";

import { useFieldArray, Controller } from "react-hook-form";
import type { FieldSchema } from "@/lib/schemas/header/header-validation";
import { Plus, Trash2 } from "lucide-react";
import { useEffect, useRef } from "react";
import { ImageUploadBlock } from "@/components/ImageUploadBlock";
import { Textarea } from "@/components/ui/textarea";

function AutoResizeTextarea({
  value,
  onChange,
  placeholder,
  className,
}: {
  value: string;
  onChange: any;
  placeholder?: string;
  className?: string;
}) {
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = "auto";
      textareaRef.current.style.height =
        textareaRef.current.scrollHeight + "px";
    }
  }, [value]);

  return (
    <Textarea
      ref={textareaRef}
      value={value}
      onChange={onChange}
      placeholder={placeholder}
      rows={1}
      className={`w-full px-4 py-2.5 bg-white border rounded-sm text-foreground text-sm font-medium focus:outline-none transition-all resize-none overflow-hidden ${className || "border-border focus:border-accent focus:ring-1 focus:ring-accent/20"}`}
    />
  );  
}

interface EditorRendererProps {
  schema: FieldSchema[];
  control: any;
  path?: string;
}

export function EditorRenderer({
  schema,
  control,
  path = "",
}: EditorRendererProps) {
  return (
    <div className="space-y-6">
      {schema.map((field) => {
        const fieldName = path ? `${path}.${field.name}` : field.name;

        if (field.type === "object") {
          return (
            <div key={fieldName} className="flex flex-col gap-6">
              <div>
                <h3 className="font-bold text-foreground text-sm">
                  {field.label}
                </h3>
                {field.description && (
                  <p className="text-xs text-muted mt-0.5">
                    {field.description}
                  </p>
                )}
              </div>
              <EditorRenderer
                schema={field.fields || []}
                control={control}
                path={fieldName}
              />
            </div>
          );
        }

        if (field.type === "image") {
          return (
            <div key={fieldName} className="flex flex-col gap-3">
              <label className="text-[13px] font-bold text-foreground uppercase tracking-wider">
                {field.label}
              </label>
              <Controller
                control={control}
                name={fieldName}
                render={({ field: { value, onChange }, fieldState }) => (
                  <div className="flex flex-col gap-1.5">
                    <ImageUploadBlock value={value} onChange={onChange} />
                    {fieldState.error && (
                      <span className="text-xs font-semibold text-red-500 bg-red-500/10 px-2 py-1 rounded-sm w-fit">
                        {fieldState.error.message ||
                          (fieldState.error as any)?.url?.message ||
                          (fieldState.error as any)?.alt?.message ||
                          "Invalid image data"}
                      </span>
                    )}
                  </div>
                )}
              />
              {field.description && (
                <p className="text-xs text-muted font-medium mt-1">
                  {field.description}
                </p>
              )}
            </div>
          );
        }

        if (field.type === "array") {
          return (
            <ArrayRenderer
              key={fieldName}
              field={field}
              fieldName={fieldName}
              control={control} 
            />
          );
        }

        // Base types (text, url, textarea)
        return (
          <div key={fieldName} className="flex flex-col gap-1.5 flex-1">
            <label className="text-xs font-bold text-foreground uppercase tracking-wider">
              {field.label}
            </label>
            <Controller
              name={fieldName}
              control={control}
              render={({
                field: { onChange, value, ref },
                fieldState: { error },
              }) => (
                <div className="flex flex-col gap-1">
                  {field.type === "textarea" ? (
                    <AutoResizeTextarea
                      value={value || ""}
                      onChange={onChange}
                      placeholder={field.placeholder}
                      className={
                        error
                          ? "border-red-500 focus:border-red-500 focus:ring-red-500/20"
                          : ""
                      }
                    />
                  ) : (
                    <input
                      ref={ref}
                      type={field.type === "url" ? "text" : field.type}
                      value={value || ""}
                      onChange={onChange}
                      placeholder={field.placeholder}
                      className={`w-full px-4 py-2.5 bg-white border rounded-sm text-foreground text-sm font-medium focus:outline-none transition-all ${
                        error
                          ? "border-red-500 focus:border-red-500 focus:ring-1 focus:ring-red-500/20"
                          : "border-border focus:border-accent focus:ring-1 focus:ring-accent/20"
                      }`}
                    />
                  )}
                  {error && (
                    <span className="text-red-500 text-[11px] font-bold tracking-wide mt-0.5">
                      {error.message}
                    </span>
                  )}
                </div>
              )}
            />
          </div>
        );
      })}
    </div>
  );
}

function ArrayRenderer({
  field,
  fieldName,
  control,
}: {
  field: FieldSchema;
  fieldName: string;
  control: any;
}) {
  const { fields, append, remove } = useFieldArray({
    control,
    name: fieldName,
  });

  return (
    <div className="space-y-4">
      {fields.map((item, index) => (
        <div
          key={item.id}
          className="bg-card-hover border border-border p-5 rounded-sm shadow-sm relative"
        >
          <div className="absolute top-0 left-0 bg-accent text-white text-[10px] font-bold px-3 py-1 rounded-br-sm rounded-tl-sm uppercase tracking-wider">
            Item {index + 1}
          </div>
          <div className="mt-2">
            <EditorRenderer
              schema={field.fields || []}
              control={control}
              path={`${fieldName}.${index}`}
            />
          </div>
        </div>
      ))}
    </div>
  );
}
