"use client";

import { useForm } from "react-hook-form";
import { useState, useEffect, useRef } from "react";
import { headerSchema } from "@/lib/schemas/header/header-validation";
import { EditorRenderer } from "@/components/EditorRenderer";
import { saveHeaderData } from "./actions";
import { Loader2 } from "lucide-react";

export default function HeaderEditorClient({ initialData }: { initialData: any }) {
  const [isSaving, setIsSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const [leftWidth, setLeftWidth] = useState(30);
  const [isDragging, setIsDragging] = useState(false);

  const iframeRef = useRef<HTMLIFrameElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const { control, handleSubmit, watch } = useForm({
    defaultValues: initialData,
  });

  const formData = watch();

  // Live preview postMessage to main.zoro
  useEffect(() => {
    if (iframeRef.current?.contentWindow) {
      iframeRef.current.contentWindow.postMessage(
        { type: "HEADER_UPDATE", data: formData },
        "*"
      );
    }
  }, [formData]);

  // Resizer drag handlers
  const handleMouseDown = () => setIsDragging(true);

  useEffect(() => {
    function handleMouseMove(e: MouseEvent) {
      if (!isDragging || !containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const newWidth = ((e.clientX - rect.left) / rect.width) * 100;
      setLeftWidth(Math.min(60, Math.max(20, newWidth)));
    }
    function handleMouseUp() {
      setIsDragging(false);
    }

    if (isDragging) {
      document.addEventListener("mousemove", handleMouseMove);
      document.addEventListener("mouseup", handleMouseUp);
      document.body.style.cursor = "col-resize";
      document.body.style.userSelect = "none";
    }

    return () => {
      document.removeEventListener("mousemove", handleMouseMove);
      document.removeEventListener("mouseup", handleMouseUp);
      document.body.style.cursor = "";
      document.body.style.userSelect = "";
    };
  }, [isDragging]);

  const onSubmit = async (data: any) => {
    setIsSaving(true);
    const result = await saveHeaderData(data);
    setIsSaving(false);
    if (result.success) {
      setSaved(true);
      setTimeout(() => setSaved(false), 2500);
    } else {
      alert("Failed to save header.");
    }
  };

  return (
    <div className="h-[calc(100vh-61px)] flex flex-col bg-background overflow-hidden">
      {/* Resizable Container */}
      <div ref={containerRef} className="flex flex-1 overflow-hidden">
        
        {/* Left: Editor Panel (30% initial width) */}
        <form
          onSubmit={handleSubmit(onSubmit)}
          style={{ width: `${leftWidth}%` }}
          className="overflow-y-auto border-r border-border bg-background flex flex-col p-6 space-y-6"
        >
          <div className="flex items-center justify-between pb-4 border-b border-border">
            <div>
              <h2 className="text-base font-extrabold text-foreground tracking-tight">
                Header Editor
              </h2>
              <p className="text-xs text-muted mt-0.5">
                Dynamic schema-driven input controls
              </p>
            </div>
            <div className="flex items-center gap-3">
              {saved && (
                <span className="text-xs text-success font-semibold animate-pulse">
                  ✓ Saved to DB
                </span>
              )}
              <button
                type="submit"
                disabled={isSaving}
                className="flex items-center justify-center bg-accent hover:bg-accent/90 text-white font-bold py-2 px-4 rounded-xl text-xs shadow-md transition-all disabled:opacity-50"
              >
                {isSaving ? (
                  <Loader2 className="animate-spin h-4 w-4" />
                ) : (
                  "Save Changes"
                )}
              </button>
            </div>
          </div>

          <EditorRenderer schema={headerSchema} control={control} />
        </form>

        {/* Resizer Handle */}
        <div
          onMouseDown={handleMouseDown}
          className="w-1.5 cursor-col-resize bg-border hover:bg-accent transition-colors shrink-0 relative group z-10"
        >
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-3 h-10 rounded-full bg-border group-hover:bg-accent transition-colors border border-background shadow flex items-center justify-center">
            <svg
              width="8"
              height="8"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="4"
              className="text-muted group-hover:text-white"
            >
              <path d="M9 18l6-6-6-6" />
            </svg>
          </div>
        </div>

        {/* Right: Live Preview Iframe (70% initial width) */}
        <div
          style={{ width: `${100 - leftWidth}%` }}
          className="overflow-hidden bg-white relative"
        >
          {/* Overlay to prevent link clicks from navigating the preview iframe */}
          <div className="absolute inset-0 z-10 pointer-events-auto bg-transparent" />
          <iframe
            ref={iframeRef}
            src="http://localhost:3001"
            className="w-full h-full border-0 pointer-events-none"
            title="Main Site Preview"
            onLoad={(e) => {
              (e.target as HTMLIFrameElement).contentWindow?.postMessage(
                { type: "HEADER_UPDATE", data: formData },
                "*"
              );
            }}
          />
        </div>
      </div>
    </div>
  );
}
